-- Tables for prototype\nCREATE TABLE IF NOT EXISTS Projects (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT\n);\nCREATE TABLE IF NOT EXISTS BoqFiles (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  project_id INTEGER,\n  filename TEXT,\n  path TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\nCREATE TABLE IF NOT EXISTS BoqItems (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  file_id INTEGER,\n  item_number TEXT,\n  description TEXT,\n  quantity TEXT,\n  unit TEXT,\n  price TEXT,\n  raw_row TEXT\n);